const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define Alabama geometry
    const alabama = ee.FeatureCollection('USGS/US_STATES')
      .filter(ee.Filter.eq('STATE_NAME', 'Alabama'))
      .first()
      .geometry();

    const startYear = 2003;
    const endYear = 2012;

    const startDate1 = ee.Date(`${startYear}-01-01`);
    const endDate1 = ee.Date(`${startYear}-12-31`);
    const startDate2 = ee.Date(`${endYear}-01-01`);
    const endDate2 = ee.Date(`${endYear}-12-31`);

    // 2. Data Acquisition & Check
    const graceCollection = ee.ImageCollection('NASA/GRACE/GRACEDADM_RL06_V1/MASCON_CRI')
      .select('wet'); // Select Water Equivalent Thickness (WET) band

    const collection2003 = graceCollection.filterDate(startDate1, endDate1);
    const collection2012 = graceCollection.filterDate(startDate2, endDate2);

    const size2003 = await collection2003.size().getInfo();
    const size2012 = await collection2012.size().getInfo();

    if (size2003 === 0 || size2012 === 0) {
      console.log(`2003 Images: ${size2003}`);
      console.log(`2012 Images: ${size2012}`);
      console.log("C1");
      return;
    }

    // Calculate mean 'wet' image for each period
    const meanImage2003 = collection2003.mean();
    const meanImage2012 = collection2012.mean();

    // 3. Processing & Calculation
    const scale = 50000; // GRACE data has coarse resolution, use a large scale
    const projection = meanImage2003.projection(); // Use the image's native projection
    const crs = projection.crs();
    const crsTransform = projection.getInfo().transform;

    // Reducer for mean water equivalent thickness
    const reducerMean = ee.Reducer.mean();

    // Reducer for pixel count
    const reducerCount = ee.Reducer.count();

    // Function to calculate mean and valid pixel count
    const calculateStats = async (image, geometry, year) => {
      const result = await image.reduceRegion({
        reducer: reducerMean.combine(reducerCount(), null, true),
        geometry: geometry,
        scale: scale,
        crs: crs,
        crsTransform: crsTransform,
        maxPixels: 1e9
      }).getInfo();

      const meanWet = result ? result['wet_mean'] : null;
      const pixelCount = result ? result['wet_count'] : 0;

      return { meanWet, pixelCount };
    };

    console.log(`2003 Images: ${size2003}`);
    const stats2003 = await calculateStats(meanImage2003, alabama, startYear);
    const meanWet2003 = stats2003.meanWet;
    const pixels2003 = stats2003.pixelCount;
    console.log(`2003 Avg WET: ${meanWet2003 !== null ? meanWet2003.toFixed(2) : 'N/A'} mm, Pixels: ${pixels2003}`);

    console.log(`2012 Images: ${size2012}`);
    const stats2012 = await calculateStats(meanImage2012, alabama, endYear);
    const meanWet2012 = stats2012.meanWet;
    const pixels2012 = stats2012.pixelCount;
    console.log(`2012 Avg WET: ${meanWet2012 !== null ? meanWet2012.toFixed(2) : 'N/A'} mm, Pixels: ${pixels2012}`);

    // 4. Validation & Final Answer
    if (pixels2003 === 0 || pixels2012 === 0) {
      console.log("C2");
      return;
    }

    if (meanWet2003 === null || isNaN(meanWet2003) || meanWet2012 === null || isNaN(meanWet2012)) {
      console.log("C3");
      return;
    }

    // Compare water storage
    if (meanWet2012 < meanWet2003) {
      console.log("A"); // Water storage decreased
    } else {
      console.log("B"); // Water storage did not decrease
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    console.log("D"); // Catch other errors like band name incorrect, memory issues etc.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
